def binary_search(nums: list[int], target: int) -> int:
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            # Found the target, but check if it's the first occurrence
            if mid == 0 or nums[mid - 1] != target:
                return mid
            right = mid - 1

    # Target not found
    return -1

