def caesar_shift(s: str, k: int) -> str:
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            shifted = (ord(char) - ord('a') + k) % 26 + ord('a')
            result.append(chr(shifted))
        elif 'A' <= char <= 'Z':
            shifted = (ord(char) - ord('A') + k) % 26 + ord('A')
            result.append(chr(shifted))
        else:
