def lru_misses(capacity: int, requests: list[int]) -> int:
    cache = []
    misses = 0
    for request in requests:
        if request in cache:
            # Move the accessed item to the end to mark it as most recently used
            cache.remove(request)
            cache.append(request)
        else:
            # If cache is not full, add the new item
            if len(cache) < capacity:
                cache.append(request)
            else:
                # Evict the least recently used item (first item in the list)
                cache.pop(0)
                cache.append(request)
            misses += 1
    return misses

