    if amount == 0:
        return 0
    if not coins:
        return -1

    # Initialize the DP array with amount + 1 to represent the maximum possible number of coins needed
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0  # Base case: 0 coins are needed to make amount 0

    # Iterate over each amount from 1 to the target amount
    for i in range(1, amount + 1):
        # Check each coin denomination
        for coin in coins:
            if i - coin >= 0:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    # If dp[amount] is still amount + 1, it means it's not possible to make the amount with the given coins
    return dp[amount] if dp[amount] != amount + 1 else -1

