def min_coins(coins: list[int], amount: int) -> int:
    if amount == 0:
        return 0

    # Initialize a list to store the minimum coins needed for each amount up to the target amount
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: 0 coins needed to make amount 0

    # Iterate through each amount from 1 to the target amount
    for i in range(1, amount + 1):
        # Check each coin to see if it can be used to make the current amount
        for coin in coins:
            if i - coin >= 0:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    # If dp[amount] is still infinity, it means the amount cannot be made
    if dp[amount] == float('inf'):
        return -1

    return dp[amount]

